import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"需","description":"周易集解 - 需","frontmatter":{"title":"需","description":"周易集解 - 需"},"headers":[],"relativePath":"zh/classics/jijie/005.md","filePath":"zh/classics/jijie/005.md"}'),l={name:"zh/classics/jijie/005.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="需" tabindex="-1">需 <a class="header-anchor" href="#需" aria-label="Permalink to “需”">​</a></h1><h2 id="需-1" tabindex="-1">需 <a class="header-anchor" href="#需-1" aria-label="Permalink to “需”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>需，有孚，光亨，貞吉。利涉大川。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物穉不可不養也，故受之以需。需者，飲食之道也。</p><p>乾寶曰：需，坤之游魂也。雲升在天，而雨未降，翱翔東西，須之象也。王事未至，飲宴之日也。夫坤者，地也；婦人之職也。百穀果蓏之所生，禽獸魚鼈之所託也，而在游魂變化之象，即烹爨腥實以為和味者也。故曰「需者，飲食之道也」。</p><p>虞翻曰：大壯四之五。孚謂五。離日為光。四之五，得位正中，故光亨。貞吉，謂壯於大輦之輻也。</p><p>何妥曰：大川者，大難也。須之待時，本欲涉難，既能以信而待，故可以利涉大川矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：需，須也，險在前也，剛健而不陷。其義不困窮矣。需，有孚，光亨，貞吉。位乎天位，以正中也。利涉大川，往有功也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>何妥曰：此明得名由於坎也。坎為險也，有險在前，不可妄涉，故須待時然後動也。</p><p>侯果曰：乾體剛健，遇險能通，險不能險，義不窮也。</p><p>蜀才曰：此本大壯卦。</p><p>案：六五降四，有孚，光亨，貞吉。九四升五，位乎天位，以正中也。</p><p>虞翻曰：謂二失位，變而涉坎，坎為大川。得位應五，故利涉大川。五多功，故往有功也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雲上於天，需。君子以飲食宴樂。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：雲上於天，須時而降也。</p><p>虞翻曰：君子謂乾。坎水兌口。水流入口為飲。二夫位，變體噬嗑為食，故以飲食。陽在內稱宴。大壯，震為樂，故宴樂也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，需於郊，利用恆，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>乾寶曰：郊，乾坎之際也。既已受命，進道北郊，未可以進，故曰需於郊。處不避污，出不辭難，臣之常節也。得位有應，故曰利用恆。雖小稽留，終於必達，故曰無咎。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：需於郊，不犯難行也。利用恆無咎，未失常也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：居需之時，最遠於險；能抑其進，不犯難行；雖不應幾，可以保常，故無咎。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，需於沙，小有言，終吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：沙謂五。水中之陽稱沙也。二變之陰，稱小。大壯震為言，兌為口。四之五，震象半見，故小有言。二變應之，故終吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：需於沙，衍在中也。雖小有言，以吉終也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：衍，流也。中謂五也。</p><p>荀爽曰：二應於五，水中之剛，故曰沙。知前有沙漠而不進也。體乾處和，美德優衍在中，而不進也。</p><p>荀爽曰：二與四同功，而三據之，故小有言。乾雖在下，終當升上，二當居五，故終吉也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，需於泥，致寇至。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：親與坎接，故稱泥。須止不進，不取於四，不致寇害。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：需於泥，災在外也。自我致寇，敬慎不敗也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：泥近乎外者也。三逼於坎，坎為險盜，故致寇至。是災在外也。</p><p>虞翻曰：離為戎，乾為敬。陰消至五遯，臣將弒君。四上壯坤，故敬慎不敗。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，需於血，出自穴。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>案：六四體坎。坎為雲，又為血卦。血以喻陰。陰體卑弱，宜順從陽，故曰需於血。</p><p>《九家易》曰：雲從地出，上升於天。自地出者，莫不由穴。故曰「需於血，出自穴」也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：需於血，順以聽也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：穴者，陰之路也。四處坎始，居穴者也。九三剛進，四不能距，見侵則避，順以聽命也。</p><p>《九家易》曰：雲欲升天，須時升降。順以聽五，五為天也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，需於酒食，貞吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>荀爽曰：五互離，坎水在火上，酒食之象。需者，飲食之道。故坎在需家，為酒食也。雲鬚時欲降，乾須時當升。五有剛德，處中居正。故能帥群陰，舉坎以降。陽能正居其所，則吉。故曰需於酒食也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：酒食貞吉，以中正也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：謂乾二當升五，正位者也。</p><p>盧氏曰：沉湎則凶，中正則吉也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，入於穴，有不速之客三人來，敬之終吉。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>荀爽曰：須道已終，雲當下，入穴也。雲上升極則降而為雨，故《詩》雲「朝躋於西，崇朝其雨」，則還入地，故曰入於穴。雲雨入地，則下三陽動而自至者也。</p><p>荀爽曰：三人，謂下三陽也。須時當升，非有召者，故曰不速之客焉。乾升在上，君位以定；坎降在下，當循臣職。故敬之終吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不速之客來，敬之終吉。雖不當位，未大失也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：上降居三，雖不當位，承陽有實，故終吉，無大失矣。</p>',77)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
